namespace SMGS.Application.Interfaces;

public record StoredFileMetadata(long Length, string ContentType);

// Keys are generated by authorized business services, never taken from upload filenames.
public interface IFileStorageService
{
    Task UploadAsync(string key, Stream content, string contentType, CancellationToken cancellationToken = default);
    Task<StoredFileMetadata?> GetMetadataAsync(string key, CancellationToken cancellationToken = default);
    Task<Stream> OpenReadAsync(string key, CancellationToken cancellationToken = default);
    Task<string> GetDownloadUrlAsync(string key, CancellationToken cancellationToken = default);
    Task DeleteAsync(string key, CancellationToken cancellationToken = default);
}

public class MediaStorageException() : Exception("Kho lưu trữ media chưa sẵn sàng. Vui lòng thử lại sau.");
